using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public class ChatEvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static IChatClient _chatClient = null!;
    private static ChatConfiguration _chatConfiguration = null!;

    [ClassInitialize]
    public static async Task ClassInitialize(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        await _appHost.BuildAsync();

        var app = await _appHost.StartAsync();
        _chatClient = app.Services.GetRequiredService<IChatClient>();
        _chatConfiguration = new ChatConfiguration(_chatClient);
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        if (_appHost is IAsyncDisposable disposable)
        {
            await disposable.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task Chat_RespondsRelevantly()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await _chatClient.GetResponseAsync(messages);

        Assert.IsNotNull(response);
        Assert.IsTrue(response.Text.Contains("Paris", StringComparison.OrdinalIgnoreCase),
            "Response should mention Paris as the capital of France.");
    }

    [TestMethod]
    public async Task Chat_EvaluateCoherence()
    {
        var coherenceEvaluator = new CoherenceEvaluator();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain what cloud computing is in one sentence.")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        var evaluationResult = await coherenceEvaluator.EvaluateAsync(
            messages,
            _chatConfiguration);

        var metric = evaluationResult.First(m => m.Name == "Coherence");
        Assert.IsTrue(metric.Rating >= EvaluationRating.Good,
            $"Coherence rating was {metric.Rating}, expected at least Good.");
    }

    [TestMethod]
    public async Task Chat_EvaluateRelevance()
    {
        var relevanceEvaluator = new RelevanceEvaluator();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What are the benefits of unit testing?")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        var evaluationResult = await relevanceEvaluator.EvaluateAsync(
            messages,
            _chatConfiguration);

        var metric = evaluationResult.First(m => m.Name == "Relevance");
        Assert.IsTrue(metric.Rating >= EvaluationRating.Good,
            $"Relevance rating was {metric.Rating}, expected at least Good.");
    }
}

