using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public class ChatEvaluationTests
{
    private static IDistributedApplicationTestingBuilder _appHost = null!;
    private static DistributedApplication _app = null!;
    private static IChatClient _chatClient = null!;
    private static ChatConfiguration _evaluatorConfig = null!;

    [ClassInitialize]
    public static async Task ClassInitialize(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await _appHost.BuildAsync();
        await _app.StartAsync();

        _chatClient = _app.Services.GetRequiredService<IChatClient>();
        _evaluatorConfig = new ChatConfiguration(_chatClient);
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        if (_app is not null)
        {
            await _app.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task Chat_RespondsRelevantly()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await _chatClient.GetResponseAsync(messages);

        Assert.IsNotNull(response);
        Assert.IsTrue(
            response.Text.Contains("Paris", StringComparison.OrdinalIgnoreCase),
            "Response should mention Paris as the capital of France.");
    }

    [TestMethod]
    public async Task Chat_EvaluateCoherence()
    {
        var evaluator = new CoherenceEvaluator();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain what cloud computing is in one sentence.")
        };

        var response = await _chatClient.GetResponseAsync(messages);

        var results = await evaluator.EvaluateAsync(messages, response, _evaluatorConfig);
        var metric = results.First(m => m.Name == CoherenceEvaluator.CoherenceMetricName);

        Assert.IsNotNull(metric.Interpretation);
        Assert.IsTrue(
            metric.Interpretation.Rating >= EvaluationRating.Good,
            $"Coherence rating was {metric.Interpretation.Rating}, expected at least Good.");
    }

    [TestMethod]
    public async Task Chat_EvaluateRelevance()
    {
        var evaluator = new RelevanceEvaluator();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What are the benefits of unit testing?")
        };

        var response = await _chatClient.GetResponseAsync(messages);

        var results = await evaluator.EvaluateAsync(messages, response, _evaluatorConfig);
        var metric = results.First(m => m.Name == RelevanceEvaluator.RelevanceMetricName);

        Assert.IsNotNull(metric.Interpretation);
        Assert.IsTrue(
            metric.Interpretation.Rating >= EvaluationRating.Good,
            $"Relevance rating was {metric.Interpretation.Rating}, expected at least Good.");
    }
}

